def titulo():
    return t("The legislative branch: how a bill becomes a law", "El poder legislativo: del proyecto a la ley")


def pasos():
    return [t("A member of Congress introduces the bill.", "Un miembro del Congreso presenta el proyecto."),
            t("A committee studies it, holds hearings, and votes to send it on.", "Un comité lo estudia, celebra audiencias y vota para enviarlo adelante."),
            t("The full chamber debates it and votes.", "El pleno de la cámara lo debate y lo vota."),
            t("The other chamber does the same: committee, debate, and vote.", "La otra cámara hace lo mismo: comité, debate y votación."),
            t("Both chambers agree on exactly the same text.", "Las dos cámaras se ponen de acuerdo en exactamente el mismo texto."),
            t("The President signs it, or vetoes it.", "El presidente lo firma o lo veta."),
            t("If vetoed, Congress can override with two-thirds of each chamber.", "Si lo veta, el Congreso puede anular el veto con dos tercios de cada cámara.")]


def svg_recorrido():
    aria = t("Flow chart of how a bill becomes a law, with exits. Steps in the center, from top to bottom: introduced; committee; vote in the first chamber; committee and vote in the second chamber; both chambers agree on the same text; the President signs or vetoes; if vetoed, Congress may override with two-thirds of each chamber. On the left, the exits where a bill dies: the committee does not act (the most common), the vote fails in either chamber, the chambers cannot agree, or the veto is not overridden. A signed bill, or an overridden veto, becomes law.",
             "Diagrama del recorrido de un proyecto hasta convertirse en ley, con sus salidas. En el centro, de arriba abajo: presentación; comité; votación en la primera cámara; comité y votación en la segunda cámara; las dos cámaras acuerdan el mismo texto; el presidente firma o veta; si veta, el Congreso puede anular el veto con dos tercios de cada cámara. A la izquierda, las salidas donde muere un proyecto: el comité no actúa (la más frecuente), la votación fracasa en cualquiera de las cámaras, las cámaras no se ponen de acuerdo o el veto no se anula. Un proyecto firmado, o un veto anulado, se convierte en ley.")
    et = [t("Introduced", "Presentación"), t("Committee", "Comité"), t("Vote, first chamber", "Votación, primera cámara"), t("Same steps, second chamber", "Lo mismo, en la otra cámara"),
          t("Same text in both chambers", "El mismo texto en las dos cámaras"), t("President: sign or veto", "Presidente: firma o veto")]
    sal = [None, t("Committee does not act:|dies quietly (most bills)", "El comité no actúa:|muere en silencio (la mayoría)"), t("Vote fails", "La votación fracasa"), t("Vote fails", "La votación fracasa"), t("No agreement", "No hay acuerdo"), None]
    s = [f'<svg class="diagrama" style="max-width:720px" viewBox="0 0 720 520" role="img" aria-label="{aria}" xmlns="http://www.w3.org/2000/svg">',
         '<defs><marker id="fl-ley" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="#5b6675"/></marker></defs>']
    for i, e in enumerate(et):
        y = 14 + i * 70
        s.append(f'<rect x="330" y="{y}" width="260" height="46" rx="10" fill="#283593"/><text x="460" y="{y + 29}" text-anchor="middle" {F} font-size="14" font-weight="700" fill="#fff">{e}</text>')
        if i < len(et) - 1:
            s.append(f'<line x1="460" y1="{y + 46}" x2="460" y2="{y + 68}" stroke="#5b6675" stroke-width="2.5" marker-end="url(#fl-ley)"/>')
        if sal[i]:
            s.append(f'<line x1="330" y1="{y + 23}" x2="292" y2="{y + 23}" stroke="#b8532c" stroke-width="2.5" stroke-dasharray="5 4" marker-end="url(#fl-ley)"/>')
            ls = sal[i].split("|")
            s.append(f'<rect x="10" y="{y + 3}" width="280" height="40" rx="8" fill="#fbece5" stroke="#b8532c"/>')
            if len(ls) == 1:
                s.append(f'<text x="150" y="{y + 28}" text-anchor="middle" {F} font-size="13" fill="#7a2e12">✕ {ls[0]}</text>')
            else:
                s.append(f'<text x="150" y="{y + 20}" text-anchor="middle" {F} font-size="13" fill="#7a2e12">✕ {ls[0]}</text><text x="150" y="{y + 36}" text-anchor="middle" {F} font-size="13" fill="#7a2e12">{ls[1]}</text>')
    y = 14 + 5 * 70
    s.append(f'<line x1="590" y1="{y + 23}" x2="640" y2="{y + 23}" stroke="#2e6b30" stroke-width="2.5" marker-end="url(#fl-ley)"/><rect x="642" y="{y + 3}" width="70" height="40" rx="8" fill="#2e6b30"/><text x="677" y="{y + 28}" text-anchor="middle" {F} font-size="14" font-weight="700" fill="#fff">{t("Law", "Ley")}</text>')
    s.append(f'<text x="615" y="{y + 15}" text-anchor="middle" {F} font-size="12" fill="#2e6b30">{t("signs", "firma")}</text>')
    s.append(f'<line x1="460" y1="{y + 46}" x2="460" y2="{y + 78}" stroke="#5b6675" stroke-width="2.5" marker-end="url(#fl-ley)"/><text x="470" y="{y + 66}" {F} font-size="12" fill="#5b6675">{t("veto", "veto")}</text>')
    y2 = y + 80
    s.append(f'<rect x="330" y="{y2}" width="260" height="46" rx="10" fill="#3949ab"/><text x="460" y="{y2 + 20}" text-anchor="middle" {F} font-size="14" font-weight="700" fill="#fff">{t("Congress votes again", "El Congreso vota otra vez")}</text><text x="460" y="{y2 + 38}" text-anchor="middle" {F} font-size="13" fill="#fff">{t("2/3 of each chamber?", "¿2/3 de cada cámara?")}</text>')
    s.append(f'<line x1="590" y1="{y2 + 23}" x2="640" y2="{y2 + 23}" stroke="#2e6b30" stroke-width="2.5" marker-end="url(#fl-ley)"/><rect x="642" y="{y2 + 3}" width="70" height="40" rx="8" fill="#2e6b30"/><text x="677" y="{y2 + 28}" text-anchor="middle" {F} font-size="14" font-weight="700" fill="#fff">{t("Law", "Ley")}</text><text x="615" y="{y2 + 15}" text-anchor="middle" {F} font-size="12" fill="#2e6b30">{t("yes", "sí")}</text>')
    s.append(f'<line x1="330" y1="{y2 + 23}" x2="292" y2="{y2 + 23}" stroke="#b8532c" stroke-width="2.5" stroke-dasharray="5 4" marker-end="url(#fl-ley)"/><rect x="10" y="{y2 + 3}" width="280" height="40" rx="8" fill="#fbece5" stroke="#b8532c"/><text x="150" y="{y2 + 28}" text-anchor="middle" {F} font-size="13" fill="#7a2e12">✕ {t("No: the veto stands", "No: el veto se mantiene")}</text>')
    s.append("</svg>")
    return "".join(s)


