def banco_camaras():
    H, S, A = t("House of Representatives", "Cámara de Representantes"), t("Senate", "Senado"), t("Both", "Las dos")
    datos = [
        (t("Has 435 members.", "Tiene 435 miembros."), 0), (t("Has two members per state.", "Tiene dos miembros por estado."), 1), (t("Its members serve two-year terms.", "Sus miembros tienen mandatos de dos años."), 0),
        (t("Holds impeachment trials.", "Celebra los juicios políticos."), 1), (t("Brings impeachment charges.", "Presenta la acusación del juicio político."), 0), (t("Confirms Supreme Court justices.", "Confirma a los jueces del Tribunal Supremo."), 1),
        (t("Must start bills to raise taxes.", "Debe iniciar los proyectos de impuestos."), 0), (t("Must pass a bill before it goes to the President.", "Debe aprobar un proyecto antes de que llegue al presidente."), 2),
        (t("Approves treaties by a two-thirds vote.", "Aprueba los tratados por dos tercios."), 1), (t("Can override a veto with two-thirds.", "Puede anular un veto con dos tercios."), 2),
        (t("Its members represent a district.", "Sus miembros representan a un distrito."), 0), (t("Allows the filibuster.", "Permite el filibusterismo."), 1),
    ]
    ops = [H, S, A]
    return [{"enun": t("House, Senate, or both?", "¿Cámara, Senado o las dos?") + "<br><strong>" + s + "</strong>", "ops": ops, "ok": k, "exp": f"<strong>{ops[k]}.</strong>", "enOrden": True} for s, k in datos]


